package com.bank.leftview;

import java.util.logging.Logger;

public class LeftViewDemo {
    private static final Logger log = Logger.getLogger(LeftViewDemo.class.getName());

    public static void main(String[] args) {
        // Tree:        1
        //            /   \
        //           2     3
        //          / \
        //         4   5         left view = [1, 2, 4]
        ViewNode root = new ViewNode(1);
        root.left = new ViewNode(2);
        root.right = new ViewNode(3);
        root.left.left = new ViewNode(4);
        root.left.right = new ViewNode(5);

        log.info("Left view: " + new LeftViewService().leftView(root));
    }
}
